Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN=300010;
int n, K, mod;
int dpArr[MAXN][20];
int cntArr[MAXN], maxPow[MAXN];
int factorial[MAXN], invFactorial[MAXN];

int quickPow(int base, int exp) {
    int res=1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return res;
}

int choose(int i, int j) {
    return (long long)factorial[i] * invFactorial[j] % mod * invFactorial[i - j] % mod;
}

int main() {
    scanf("%d%d%d", &n, &K, &mod);
    int i, j, k;
    int totalAns=0;
    int mask, rem, tmpVal, cur, c1, c2;

    if (n & 1) {
        printf("%d\n", quickPow(K, n));
        return 0;
    }

    factorial[0]=1;
    for (i=1; i<=n; i++) factorial[i] = (long long)factorial[i-1]*i % mod;

    invFactorial[n] = quickPow(factorial[n], mod-2);
    for (i=n-1; i>=1; i--) invFactorial[i] = (long long)invFactorial[i+1]*(i+1) % mod;

    for (i=1; i<=n; i++) {
        for (j=0; j<=18; j++) {
            if ((1<<j) & i) cntArr[i]++;
        }
    }

    for (i=1; i<=n; i++) {
        for (j=18; j>=0; j--) {
            if ((1<<j) & i) {
                maxPow[i] = 1<<j;
                break;
            }
        }
    }

    memset(dpArr, 0, sizeof(dpArr));
    dpArr[0][0] = 1;

    for (i=1; i<=n; i++) {
        if ((n & i) != i) continue;
        rem = i ^ maxPow[i];
        for (mask=rem; ; mask=(mask-1)&rem) {
            cur = mask + maxPow[i];
            c2 = i ^ cur;
            int limit = min(K-1, cntArr[c2]);
            int tmpVal = choose(i, cur);
            for (j=0; j<=limit; j++) {
                dpArr[i][j+1] = (dpArr[i][j+1] + (long long)dpArr[c2][j] * tmpVal) % mod;
            }
            if (mask == 0) break;
        }
    }

    for (j=1; j<=min(cntArr[n], K); j++) {
        totalAns = (totalAns + (long long)dpArr[n][j] * choose(K, j) % mod * factorial[j]) % mod;
    }

    totalAns = (quickPow(K, n) - totalAns + mod) % mod;
    printf("%d\n", totalAns);
    return 0;
}
